 * @hidden N
 */
scwin.btn_upload_onclick = async function (e) {
    try {
        await scwin.feeCalcUploadPop();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL05040.btn_upload_onclick" });
    }
};

