///////// 4. 서브미션 콜백 영역 /////////
/*
 * 엑셀 다운로드
 */
scwin.saveExcel = async function(){

    if(scwin.rsltFlag === "Y") {
        const sbmOptions = {
            id : "sbm_saveHdnchamp",
            action : "/api/listing/applsubmit/elwappl/listing-fee-calc/calc-result-download",
            method : "post",
            ref : "dma_hdnchampReqRes",
            isProcessMsg : true
        };

        const res =  await $c.sbm.executeDynamic(sbmOptions);
        if (res.responseJSON.success === true) {
            await $c.win.alert(sText+' 처리 성공했습니다.');
            $c.win.closeAllPopup();
        }

    } else {
        $c.win.alert( '계산된 결과가 없습니다.');
    }
};

/*
 * 인쇄
 */
scwin.print = async function(){

    if(scwin.rsltFlag === "Y") {

        const params = {
            "printListDto" : dlt_resultCalc.getAllJSON()
            ,"totFee"       : ibx_totFee.getValue()
        }

        const jsonData = JSON.stringify(params);
        const sbmOptions = {
            id: "sbm_print",
            action: "/api/listing/applsubmit/elwappl/listing-fee-calc/calc-result-print",
            method: "post",
        };

        const res = await $c.sbm.executeDynamic(sbmOptions, jsonData);

        if(res.responseJSON.success === true)  {
            // TODO Stage2: 프로젝트 공통 $c.win.popupPrint 는 gcc 에 없다(gcc $c.win.print 는 화면 캡처 인쇄). 서버가 돌려준 인쇄 HTML 표시 방식 결정 후 대체
            await $c.win.popupPrint(res.responseJSON.body); // 인쇄
        }
    } else {
        $c.win.alert( '계산된 결과가 없습니다.');
    }

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name rules
 * @description ELW 계산원칙 안내 팝업을 연다.
 * @returns {void}
 * @hidden N
 */
scwin.rules = function() {

    const url = "/ui/lst/helper/ULDFIL35709.xml";
    const popTitle = "ELW 계산원칙";

    const opts = {
        id: "ULDFIL35709",
        popupName: popTitle,
        width: 700,
        height: 700,
        frameModal: "top",
    };

    $c.win.openPopup(url, opts);
};

