/**
 * @method
 * @name openFormSubmit
 * @description 폼(Form) 동적 생성 및 제출 공통함수
 * @param {string} url - 요청할 엔드포인트 URL
 * @hidden N
 * @param {Object} [params={}] - 전송할 key-value 데이터 객체
 * @param {Object} [options={}] - 추가 옵션 (method, target, removeAfterSubmit)
 * @param {string} [options.method='POST'] - HTTP 메소드 ('POST', 'GET')
 * @param {string} [options.target='_self'] - 제출 대상 ('_self', '_blank', 또는 iframe name)
 * @param {boolean} [options.removeAfterSubmit=true] - 제출 후 DOM에서 form 제거 여부
 * @example
 * const url = "/api/listing/applsubmit/elwappl/listing-fee-calc/template-download";
 * const params = {};
 * const options = {
 * 	   method : "GET"
 * };
 * $c.win.openFormSubmit(url, params, options);
 * @returns {void}
 */
scwin.openFormSubmit = function(url, params = {}, options = {}) {
    const {
        method = 'GET',
        target = '_self',
        removeAfterSubmit = true
    } = options;

    // 1. Form 엘리먼트 생성 및 속성 설정
    const form = document.createElement('form');
    form.method = method.toUpperCase();
    form.action = "/api/listing/applsubmit/elwappl/listing-fee-calc/template-download";
    form.target = target;
    form.style.display = 'none';

    // 2. 파라미터 객체를 hidden input으로 변환하여 추가
    Object.entries(params).forEach(([key, value]) => {
        // 배열이나 객체 형태 처리 (문자열 변환)
        const val = typeof value === 'object' ? JSON.stringify(value) : value;

        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = key;
        input.value = val ?? '';
        form.appendChild(input);
    });

    // 3. DOM에 추가 후 제출
    document.body.appendChild(form);
    form.submit();

    // 4. 제출 후 DOM 정리
    if (removeAfterSubmit) {
        // submit 직후 삭제하면 일부 브라우저에서 취소될 수 있어 약간의 지연 후 삭제
        setTimeout(() => {
            form.remove();
        }, 100);
    }
};

/**
 * @method
 * @name feeCalcUploadPop
 * @description 양식 파일업로드 팝업을 열고 결과 데이터를 그리드에 반영한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.feeCalcUploadPop = async function() {

    scwin.rsltFlag = "N";

    let url = "/ui/lst/list/ULDFIL05040_i0.xml";
    let popTitle = "양식 파일업로드";

    const opts = {
        id: "ULDFIS00300_P3",
        popupName: popTitle,
        width: 800,
        height: 700,
        frameModal: "top",
    };

    const childData =  await $c.win.openPopup(url, opts);

    if(childData.length > 0) await scwin.setGridData(childData);
};

/**
 * @method
 * @name setGridData
 * @description 업로드 팝업이 돌려준 데이터를 결과 그리드에 세팅한다.
 * @param {Array} childData 데이터 배열
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setGridData = async function(childData){

dlt_resultCalc.setBroadcast(false);
for(let i = 0; i < childData.length; i++) {
    dlt_resultCalc.insertRow(i);
    dlt_resultCalc.setCellData(i, "isuAbbrv", childData[i].isuAbbrv );
    dlt_resultCalc.setCellData(i, "isuQty", childData[i].isuQty );
    dlt_resultCalc.setCellData(i, "isuPrc", childData[i].isuPrc );
    dlt_resultCalc.setCellData(i, "isuTotamt", childData[i].isuTotamt );
    dlt_resultCalc.setCellData(i, "isuFee", childData[i].isuFee );
}
dlt_resultCalc.setBroadcast(true, true);
    ibx_totFee.setValue(childData[0].isuTotFee)

    scwin.rsltFlag = "Y";
};

/*
 * 초기화
 */
scwin.reset = function(){

    if(scwin.rsltFlag  === "Y") {
        scwin.rsltFlag  = "N"
        ibx_totFee.setValue("");

        // document.getElementById("feeCalcDiv_data").innerHTML = "";
        dlt_resultCalc.removeAll();
        // $("#feeCalcDiv_data").hide();
        // $("#feeCalcDiv").show();
    } else {
        $c.win.alert( '계산된 결과가 없습니다.');
    }
};
